import * as strings from "std/string";
import * as rental from "host/rental";
import * as organizer from "host/organizer";

export class RentalOption {
    id: string = "";
    title: string = "";
    detail: string = "";
    price: string = "";
    totalCents: int = 0;
    selected: boolean = false;
}

export class State {
    quantity: int = 1;
    budgetCents: int = 2000;
    search: string = "";
    periodStart: string = "2026-10-10T16:00:00Z";
    periodEnd: string = "2026-10-10T22:00:00Z";
    quantityError: string = "";
    budgetError: string = "";
    valid: boolean = true;
    editing: boolean = true;
    canLoad: boolean = true;
    canPrepare: boolean = false;
    loading: boolean = false;
    preparing: boolean = false;
    rows: RentalOption[] = [];
    selectedId: string = "";
    hasSelection: boolean = false;
    prepared: boolean = false;
    loaded: boolean = false;
    empty: boolean = false;
    loadError: string = "";
    prepareError: string = "";
}

export class ChangeQuantity {
    value: int = 1;
}

export class ChangeBudget {
    value: int = 2000;
}

export class ChangeSearch {
    value: string = "";
}

export class PickOption {
    value: string = "";
}

export class LoadOptions {}

export class OptionsLoaded {
    rows: RentalOption[] = [];
    error: string = "";
}

export class PrepareReview {}

export class ReviewPrepared {
    success: boolean = false;
    error: string = "";
}

function asciiLower(text: string): string {
    let upper: string = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let lower: string = "abcdefghijklmnopqrstuvwxyz";
    let result: string = "";
    for (let character: string of text) {
        let replacement: string = character;
        for (let i: int = 0; i < 26; i = i + 1) {
            if (character === strings.substring(upper, i, i + 1)) {
                replacement = strings.substring(lower, i, i + 1);
            }
        }
        result = result + replacement;
    }
    return result;
}

function decimal(value: int): string {
    if (value === 0) {
        return "0";
    }
    let digits: string = "0123456789";
    let remaining: int = value;
    let result: string = "";
    while (remaining > 0) {
        let digit: int = remaining % 10;
        result = strings.substring(digits, digit, digit + 1) + result;
        remaining = remaining / 10;
    }
    return result;
}

function euroPrice(cents: int): string {
    let fraction: int = cents % 100;
    let fractionText: string = decimal(fraction);
    if (fraction < 10) {
        fractionText = "0" + fractionText;
    }
    return "€" + decimal(cents / 100) + "." + fractionText;
}

function buildState(quantity: int, budgetCents: int, search: string, loading: boolean, preparing: boolean, sourceRows: RentalOption[], selectedId: string, hasSelection: boolean, prepared: boolean, loaded: boolean, loadError: string, prepareError: string): State {
    let quantityError: string = "";
    let budgetError: string = "";
    if (quantity < 1 || quantity > 8) {
        quantityError = "Quantity must be between 1 and 8.";
    }
    if (budgetCents < 0 || budgetCents > 100000) {
        budgetError = "Budget must be between 0 and 100000 cents.";
    }
    let valid: boolean = quantityError === "" && budgetError === "";
    let editing: boolean = !loading && !preparing;
    let rows: RentalOption[] = [];
    for (let row: RentalOption of sourceRows) {
        let copied: RentalOption = {
            id: row.id,
            title: row.title,
            detail: row.detail,
            price: row.price,
            totalCents: row.totalCents,
            selected: hasSelection && row.id === selectedId
        };
        rows[rows.length] = copied;
    }
    return {
        quantity: quantity,
        budgetCents: budgetCents,
        search: search,
        periodStart: "2026-10-10T16:00:00Z",
        periodEnd: "2026-10-10T22:00:00Z",
        quantityError: quantityError,
        budgetError: budgetError,
        valid: valid,
        editing: editing,
        canLoad: valid && editing,
        canPrepare: valid && editing && hasSelection && !prepared,
        loading: loading,
        preparing: preparing,
        rows: rows,
        selectedId: selectedId,
        hasSelection: hasSelection,
        prepared: prepared,
        loaded: loaded,
        empty: loaded && rows.length === 0,
        loadError: loadError,
        prepareError: prepareError
    };
}

function copyState(state: State): State {
    return buildState(state.quantity, state.budgetCents, state.search, state.loading, state.preparing, state.rows, state.selectedId, state.hasSelection, state.prepared, state.loaded, state.loadError, state.prepareError);
}

function editedState(quantity: int, budgetCents: int, search: string): State {
    let rows: RentalOption[] = [];
    return buildState(quantity, budgetCents, search, false, false, rows, "", false, false, false, "", "");
}

export function initialState(): State {
    return {};
}

export function main(): null {
    return null;
}

// @ui-update
export function changeQuantity(state: State, action: ChangeQuantity): State {
    if (!state.editing) {
        return copyState(state);
    }
    return editedState(action.value, state.budgetCents, state.search);
}

// @ui-update
export function changeBudget(state: State, action: ChangeBudget): State {
    if (!state.editing) {
        return copyState(state);
    }
    return editedState(state.quantity, action.value, state.search);
}

// @ui-update
export function changeSearch(state: State, action: ChangeSearch): State {
    if (!state.editing) {
        return copyState(state);
    }
    return editedState(state.quantity, state.budgetCents, action.value);
}

// @ui-update
export function pickOption(state: State, action: PickOption): State {
    if (!state.editing || !state.valid) {
        return copyState(state);
    }
    let found: boolean = false;
    for (let row: RentalOption of state.rows) {
        if (row.id === action.value) {
            found = true;
        }
    }
    if (!found) {
        return copyState(state);
    }
    return buildState(state.quantity, state.budgetCents, state.search, false, false, state.rows, action.value, true, false, state.loaded, "", "");
}

// @ui-update
export function beginLoad(state: State, action: LoadOptions): State {
    if (!state.canLoad) {
        return copyState(state);
    }
    let rows: RentalOption[] = [];
    return buildState(state.quantity, state.budgetCents, state.search, true, false, rows, "", false, false, false, "", "");
}

// @ui-effect
export async function loadOptions(state: State, action: LoadOptions): OptionsLoaded {
    if (!state.valid || state.preparing) {
        return { error: "Enter a quantity from 1 to 8 and a valid budget before loading." };
    }
    try {
        let records: table[] = await rental.equipment(state.periodStart, state.periodEnd);
        let query: string = asciiLower(strings.trim(state.search));
        let rows: RentalOption[] = [];
        for (let record: table of records) {
            let id: string = record.id;
            let title: string = record.name;
            let specification: string = record.specification;
            let cents: int = record.cents;
            let available: int = record.available;
            let searchable: string = asciiLower(title + " " + specification);
            let matchesRequirement: boolean = strings.contains(searchable, "boom") && strings.contains(searchable, "stand");
            let matchesSearch: boolean = query === "" || strings.contains(searchable, query);
            if (matchesRequirement && matchesSearch && available >= state.quantity && cents >= 0) {
                if (cents <= state.budgetCents / state.quantity) {
                    let total: int = cents * state.quantity;
                    let row: RentalOption = {
                        id: id,
                        title: title,
                        detail: specification,
                        price: euroPrice(total) + " total",
                        totalCents: total,
                        selected: false
                    };
                    rows[rows.length] = row;
                }
            }
        }
        return { rows: rows, error: "" };
    } catch (e) {
        return { error: "Rental catalogue unavailable: " + e.message };
    }
}

// @ui-update
export function finishLoad(state: State, action: OptionsLoaded): State {
    if (!state.loading) {
        return copyState(state);
    }
    if (action.error !== "") {
        let rows: RentalOption[] = [];
        return buildState(state.quantity, state.budgetCents, state.search, false, false, rows, "", false, false, false, action.error, "");
    }
    return buildState(state.quantity, state.budgetCents, state.search, false, false, action.rows, "", false, false, true, "", "");
}

// @ui-update
export function beginPreparation(state: State, action: PrepareReview): State {
    if (!state.canPrepare) {
        return copyState(state);
    }
    return buildState(state.quantity, state.budgetCents, state.search, false, true, state.rows, state.selectedId, state.hasSelection, false, state.loaded, "", "");
}

// @ui-effect
export async function prepareReview(state: State, action: PrepareReview): ReviewPrepared {
    if (!state.valid || !state.hasSelection || state.loading || state.prepared) {
        return { success: false, error: "Select a qualifying option before preparing it for review." };
    }
    try {
        for (let row: RentalOption of state.rows) {
            if (row.id === state.selectedId) {
                let detail: string = "Item " + row.id + ":" + decimal(state.quantity) + "; from " + state.periodStart + "; until " + state.periodEnd;
                let result: table = await organizer.stage("rental", "host/rental", row.title, detail, euroPrice(row.totalCents), state.periodEnd);
                let staged: boolean = result.staged;
                if (!staged) {
                    return { success: false, error: "The local preparation capability did not prepare this item. Try again." };
                }
                return { success: true, error: "" };
            }
        }
        return { success: false, error: "The selected option is no longer available in this shortlist. Load options again." };
    } catch (e) {
        return { success: false, error: "Local preparation unavailable: " + e.message };
    }
}

// @ui-update
export function finishPreparation(state: State, action: ReviewPrepared): State {
    if (!state.preparing) {
        return copyState(state);
    }
    let error: string = action.error;
    if (!action.success && error === "") {
        error = "Local preparation failed. Try again.";
    }
    if (action.success) {
        error = "";
    }
    return buildState(state.quantity, state.budgetCents, state.search, false, false, state.rows, state.selectedId, state.hasSelection, action.success, state.loaded, "", error);
}

