import * as app from "./experience";
import * as ui from "./platform.dealui-pack";

// @ui-root
export view RentalShortlist(state: app.State): View {
    ui.Column() {
        ui.Text(value: "Rental shortlist")
        ui.Text(value: "Boom stand · Adjustable boom")
        ui.Text(value: "2026-10-10T16:00:00Z — 2026-10-10T22:00:00Z")
        ui.Notice(text: "Search is restricted to boom stands: both boom and stand must appear in the name or specification. Editing quantity, budget or search clears the options, selection and preparation success.", tone: "info")
        ui.Card() {
            ui.IntField(value: state.quantity, label: "Quantity", minimum: 0, maximum: 9, step: 1, enabled: state.editing, supporting: "Enter 1 to 8. Values 0 and 9 are invalid.", error: state.quantityError, onChange: action app.ChangeQuantity { value: payload }, accessibilityLabel: "Quantity")
            ui.IntField(value: state.budgetCents, label: "Total budget in cents", minimum: 0, maximum: 100000, step: 100, enabled: state.editing, supporting: "Total budget for all units, in cents. Options must fit this total.", error: state.budgetError, onChange: action app.ChangeBudget { value: payload }, accessibilityLabel: "Budget")
            ui.SearchField(value: state.search, label: "Search", multiline: false, enabled: state.editing, supporting: "Further narrow boom stands by name or specification. Whitespace is trimmed and ASCII case is ignored; an empty search accepts all qualifying stands.", error: "", onChange: action app.ChangeSearch { value: payload }, accessibilityLabel: "Search")
            When(state.loadError === "") {
                ui.Button(text: "Load options", enabled: state.canLoad, onClick: action app.LoadOptions {}, accessibilityLabel: "Load options")
            }
        }
        When(state.loading) {
            ui.Progress(label: "Loading")
        }
        When(state.loadError !== "") {
            ui.Text(value: "The rental catalogue could not be read. No option has been selected.")
            ui.Failure(text: state.loadError, onRetry: action app.LoadOptions {}, accessibilityLabel: "Retry loading options")
        }
        When(state.empty) {
            ui.Text(value: "No qualifying options")
            ui.Text(value: "Try changing the search, quantity or total budget, then load again. Results must still match both boom and stand.")
        }
        When(state.loaded) {
            ui.Section(title: "Qualifying options", summary: "Prices are totals for the requested quantity. Select one option for local preparation.") {
                ForEach(state.rows, row: app.RentalOption, key: row.id) {
                    ui.Option(value: row.id, title: row.title, detail: row.detail, price: row.price, meta: "Available for the disclosed period", selected: row.selected, enabled: state.editing, onSelect: action app.PickOption { value: payload }, accessibilityLabel: row.title)
                }
                When(state.empty) {
                    ui.Text(value: "No options meet every requirement.")
                }
            }
        }
        When(state.hasSelection) {
            ui.Card() {
                ui.Text(value: "Review preparation")
                ui.Text(value: "Prepare the selected item locally for native review. This does not reserve equipment or confirm a rental.")
                When(state.preparing) {
                    ui.Progress(label: "Preparing for native review")
                }
                When(state.prepared) {
                    ui.Notice(text: "Prepared for native review", tone: "info")
                    ui.Text(value: "Your selection is preserved. Any permission or confirmation happens outside this shortlist.")
                } Else {
                    When(state.prepareError !== "") {
                        ui.Text(value: "Local preparation failed. Your selection has been retained.")
                        ui.Failure(text: state.prepareError, onRetry: action app.PrepareReview {}, accessibilityLabel: "Retry preparation for native review")
                    } Else {
                        ui.Button(text: "Prepare for review", enabled: state.canPrepare, onClick: action app.PrepareReview {}, accessibilityLabel: "Prepare for review")
                    }
                }
            }
        }
    }
}
